const state = {
  characters: [
    { id: "teacher", name: "老師", side: "left", avatarType: "image", avatarFile: "profile.png", avatarText: "師" },
    { id: "student", name: "學生", side: "rightNoAvatar", avatarType: "image", avatarFile: "people.png", avatarText: "學" },
    { id: "parent", name: "家長", side: "left", avatarType: "image", avatarFile: "user (1).png", avatarText: "家" },
  ],
  messages: [
    {
      characterId: "teacher",
      time: "09:10",
      text: "今天請大家討論：為什麼寫作前要先列大綱？",
    },
    {
      characterId: "student",
      time: "09:12",
      text: "我覺得列大綱可以先整理順序，寫文章時比較不會跳來跳去。",
    },
    {
      characterId: "parent",
      time: "09:13",
      text: "也可以幫助孩子確認重點是不是完整。",
    },
  ],
};

const els = {
  title: document.querySelector("#chatTitle"),
  pageWidth: document.querySelector("#pageWidth"),
  showTime: document.querySelector("#showTime"),
  characters: document.querySelector("#characters"),
  messages: document.querySelector("#messages"),
  svg: document.querySelector("#chatSvg"),
  addCharacter: document.querySelector("#addCharacter"),
  addMessage: document.querySelector("#addMessage"),
  downloadPng: document.querySelector("#downloadPng"),
  downloadSvg: document.querySelector("#downloadSvg"),
  printPdf: document.querySelector("#printPdf"),
};

const SVG_NS = "http://www.w3.org/2000/svg";
const FONT_FAMILY = '"Noto Sans TC", "Microsoft JhengHei", Arial, sans-serif';
const avatarOptions = [
  { value: "__text__", label: "頭像字" },
  { value: "profile.png", label: "profile" },
  { value: "people.png", label: "people" },
  { value: "people (1).png", label: "people-1" },
  { value: "user (1).png", label: "user-1" },
  { value: "user (2).png", label: "user-2" },
  { value: "user (3).png", label: "user-3" },
  { value: "user (4).png", label: "user-4" },
  { value: "friendship.png", label: "friendship" },
  { value: "love.png", label: "love" },
  { value: "users.png", label: "users" },
];

const avatarData = {
  "profile.png": "data:image/png;base64,",
  "people.png": "data:image/png;base64,",
  "people (1).png": "data:image/png;base64,",
  "user (1).png": "data:image/png;base64,",
  "user (2).png": "data:image/png;base64,",
  "user (3).png": "data:image/png;base64,",
  "user (4).png": "data:image/png;base64,",
  "friendship.png": "data:image/png;base64,",
  "love.png": "data:image/png;base64,",
  "users.png": "data:image/png;base64,"
};

function getAvatarSrc(filename) {
  return avatarData[filename] || filename;
}


function uid(prefix) {
  return `${prefix}-${Math.random().toString(36).slice(2, 9)}`;
}

function svgEl(tag, attrs = {}) {
  const node = document.createElementNS(SVG_NS, tag);
  Object.entries(attrs).forEach(([key, value]) => node.setAttribute(key, value));
  return node;
}

function measureText(text, fontSize = 22) {
  const canvas = measureText.canvas || (measureText.canvas = document.createElement("canvas"));
  const ctx = canvas.getContext("2d");
  ctx.font = `${fontSize}px ${FONT_FAMILY}`;
  return ctx.measureText(text).width;
}

function wrapText(text, maxWidth, fontSize) {
  const lines = [];
  const paragraphs = String(text || "").split("\n");

  paragraphs.forEach((paragraph) => {
    let line = "";
    Array.from(paragraph).forEach((char) => {
      const trial = line + char;
      if (line && measureText(trial, fontSize) > maxWidth) {
        lines.push(line);
        line = char;
      } else {
        line = trial;
      }
    });
    lines.push(line || " ");
  });

  return lines;
}

function getCharacter(id) {
  return state.characters.find((character) => character.id === id) || state.characters[0];
}

function renderEditors() {
  els.characters.innerHTML = "";
  state.characters.forEach((character, index) => {
    const row = document.createElement("div");
    row.className = "row-card row-grid";
    row.innerHTML = `
      <label>名稱<input type="text" value="${escapeHtml(character.name)}" data-field="name"></label>
      <label>頭像字<input type="text" maxlength="2" value="${escapeHtml(character.avatarText || "")}" data-field="avatarText"></label>
      <label>人物頭像<select data-field="avatarFile">
        ${avatarOptions
          .map(
            (option) => {
              const selected = option.value === "__text__"
                ? !character.avatarFile
                : character.avatarFile === option.value;
              return `<option value="${option.value}" ${selected ? "selected" : ""}>${escapeHtml(option.label)}</option>`;
            },
          )
          .join("")}
      </select></label>
      <label>位置<select data-field="side">
        <option value="left" ${character.side === "left" ? "selected" : ""}>左側</option>
        <option value="right" ${character.side === "right" ? "selected" : ""}>右側</option>
        <option value="rightNoAvatar" ${character.side === "rightNoAvatar" ? "selected" : ""}>右邊</option>
      </select></label>
      <button class="remove-btn" type="button" aria-label="刪除角色">×</button>
    `;

    row.querySelector('[data-field="name"]').addEventListener("input", (event) => {
      character.name = event.target.value || `角色 ${index + 1}`;
      renderMessages();
      renderSvg();
    });
    row.querySelector('[data-field="avatarText"]').addEventListener("input", (event) => {
      character.avatarText = event.target.value || Array.from(character.name || "?")[0];
      renderSvg();
    });
        row.querySelector('[data-field="avatarFile"]').addEventListener("change", (event) => {
      if (event.target.value === "__text__") {
        character.avatarType = "text";
        character.avatarFile = "";
      } else {
        character.avatarType = "image";
        character.avatarFile = event.target.value;
      }
      renderSvg();
    });
    row.querySelector('[data-field="side"]').addEventListener("change", (event) => {
      character.side = event.target.value;
      renderSvg();
    });
    row.querySelector(".remove-btn").addEventListener("click", () => {
      if (state.characters.length <= 1) return;
      state.characters = state.characters.filter((item) => item.id !== character.id);
      state.messages.forEach((message) => {
        if (message.characterId === character.id) {
          message.characterId = state.characters[0].id;
        }
      });
      renderAll();
    });

    els.characters.appendChild(row);
  });
}

function renderMessages() {
  els.messages.innerHTML = "";
  state.messages.forEach((message) => {
    const row = document.createElement("div");
    row.className = "row-card message-grid";

    const options = state.characters
      .map(
        (character) =>
          `<option value="${character.id}" ${
            message.characterId === character.id ? "selected" : ""
          }>${escapeHtml(character.name)}</option>`,
      )
      .join("");

    row.innerHTML = `
      <label>角色<select data-field="characterId">${options}</select></label>
      <label>時間<input type="text" value="${escapeHtml(message.time)}" data-field="time"></label>
      <label>文字<textarea data-field="text">${escapeHtml(message.text)}</textarea></label>
      <button class="remove-btn" type="button" aria-label="刪除訊息">×</button>
    `;

    row.querySelector('[data-field="characterId"]').addEventListener("change", (event) => {
      message.characterId = event.target.value;
      renderSvg();
    });
    row.querySelector('[data-field="time"]').addEventListener("input", (event) => {
      message.time = event.target.value;
      renderSvg();
    });
    row.querySelector('[data-field="text"]').addEventListener("input", (event) => {
      message.text = event.target.value;
      renderSvg();
    });
    row.querySelector(".remove-btn").addEventListener("click", () => {
      state.messages = state.messages.filter((item) => item !== message);
      renderAll();
    });

    els.messages.appendChild(row);
  });
}

function renderSvg() {
  const width = Number(els.pageWidth.value);
  const padding = 26;
  const headerHeight = 76;
  const avatarSize = 42;
  const gap = 16;
  const bubbleMaxWidth = Math.min(430, Math.max(230, width - 170));
  const fontSize = 21;
  const lineHeight = 30;
  let y = headerHeight + 24;

  els.svg.innerHTML = "";
  els.svg.setAttribute("width", width);
  els.svg.setAttribute("viewBox", `0 0 ${width} 100`);

  els.svg.appendChild(svgEl("rect", { x: 0, y: 0, width, height: 100, fill: "#fff" }));
  els.svg.appendChild(svgEl("rect", { x: 0, y: 0, width, height: headerHeight, fill: "#111" }));
  els.svg.appendChild(
    textNode(els.title.value || "對話", padding, 48, {
      size: 25,
      weight: 700,
      fill: "#fff",
    }),
  );

  state.messages.forEach((message) => {
    const character = getCharacter(message.characterId);
    const side = character.side;
    const isRight = side === "right" || side === "rightNoAvatar";
    const showAvatar = side !== "rightNoAvatar";
    const lines = wrapText(message.text, bubbleMaxWidth - 34, fontSize);
    const textWidth = Math.min(
      bubbleMaxWidth,
      Math.max(96, ...lines.map((line) => measureText(line, fontSize) + 34)),
    );
    const bubbleHeight = lines.length * lineHeight + 26;
    const rowHeight = Math.max(bubbleHeight + 34, avatarSize + 34);
    const avatarX = isRight ? width - padding - avatarSize : padding;
    const bubbleX = isRight
      ? width - padding - textWidth - (showAvatar ? avatarSize + gap : 0)
      : avatarX + avatarSize + gap;
    const nameX = isRight ? bubbleX + textWidth : bubbleX;
    const nameAnchor = isRight ? "end" : "start";

    if (showAvatar) {
      drawAvatar(avatarX, y, avatarSize, character);
    }
    els.svg.appendChild(
      textNode(character.name, nameX, y + 14, {
        size: 14,
        fill: "#333",
        anchor: nameAnchor,
      }),
    );
    drawBubble(bubbleX, y + 22, textWidth, bubbleHeight, isRight ? "right" : "left");

    lines.forEach((line, lineIndex) => {
      els.svg.appendChild(
        textNode(line, bubbleX + 17, y + 56 + lineIndex * lineHeight, {
          size: fontSize,
          fill: "#111",
        }),
      );
    });

    if (els.showTime.checked && message.time) {
      const timeX = isRight ? bubbleX - 10 : bubbleX + textWidth + 10;
      const timeAnchor = isRight ? "end" : "start";
      els.svg.appendChild(
        textNode(message.time, timeX, y + bubbleHeight + 18, {
          size: 13,
          fill: "#555",
          anchor: timeAnchor,
        }),
      );
    }

    y += rowHeight;
  });

  const height = y + 22;
  els.svg.setAttribute("height", height);
  els.svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
  els.svg.querySelector("rect").setAttribute("height", height);
}

function drawAvatar(x, y, size, character) {
  if (character.avatarFile) {
    const clipId = `avatar-clip-${Math.random().toString(36).slice(2, 9)}`;
    const defs = svgEl("defs");
    const clip = svgEl("clipPath", { id: clipId });
    clip.appendChild(svgEl("circle", { cx: x + size / 2, cy: y + size / 2, r: size / 2 }));
    defs.appendChild(clip);
    els.svg.appendChild(defs);

    const image = svgEl("image", {
      x,
      y,
      width: size,
      height: size,
      href: getAvatarSrc(character.avatarFile),
      preserveAspectRatio: "xMidYMid slice",
      "clip-path": `url(#${clipId})`,
    });
    image.setAttributeNS("http://www.w3.org/1999/xlink", "href", getAvatarSrc(character.avatarFile));
    els.svg.appendChild(image);
    els.svg.appendChild(
      svgEl("circle", {
        cx: x + size / 2,
        cy: y + size / 2,
        r: size / 2,
        fill: "none",
        stroke: "#111",
        "stroke-width": 2,
      }),
    );
    return;
  }

  els.svg.appendChild(
    svgEl("circle", {
      cx: x + size / 2,
      cy: y + size / 2,
      r: size / 2,
      fill: "#fff",
      stroke: "#111",
      "stroke-width": 2,
    }),
  );
  els.svg.appendChild(
    textNode(character.avatarText || "?", x + size / 2, y + size / 2 + 8, {
      size: 22,
      weight: 700,
      anchor: "middle",
      fill: "#111",
    }),
  );
}

function drawBubble(x, y, width, height, side) {
  const bubble = svgEl("rect", {
    x,
    y,
    width,
    height,
    rx: 10,
    ry: 10,
    fill: side === "left" ? "#fff" : "#f0f0f0",
    stroke: "#111",
    "stroke-width": 2,
  });
  els.svg.appendChild(bubble);

  const tail =
    side === "left"
      ? `${x},${y + 20} ${x - 10},${y + 28} ${x},${y + 36}`
      : `${x + width},${y + 20} ${x + width + 10},${y + 28} ${x + width},${y + 36}`;
  els.svg.appendChild(
    svgEl("polygon", {
      points: tail,
      fill: side === "left" ? "#fff" : "#f0f0f0",
      stroke: "#111",
      "stroke-width": 2,
      "stroke-linejoin": "round",
    }),
  );
}

function textNode(value, x, y, options = {}) {
  const text = svgEl("text", {
    x,
    y,
    fill: options.fill || "#111",
    "font-size": options.size || 18,
    "font-weight": options.weight || 400,
    "font-family": FONT_FAMILY,
    "text-anchor": options.anchor || "start",
  });
  text.textContent = value;
  return text;
}

function escapeHtml(value) {
  return String(value || "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function getSvgString() {
  renderSvg();
  const clone = els.svg.cloneNode(true);
  clone.setAttribute("xmlns", SVG_NS);
  return `<?xml version="1.0" encoding="UTF-8"?>\n${new XMLSerializer().serializeToString(clone)}`;
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function downloadSvg() {
  downloadBlob(new Blob([getSvgString()], { type: "image/svg+xml;charset=utf-8" }), "line-dialogue.svg");
}

function loadCanvasImage(src) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = reject;
    image.src = src;
  });
}

function drawRoundRect(ctx, x, y, width, height, radius) {
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + width - radius, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
  ctx.lineTo(x + width, y + height - radius);
  ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
  ctx.lineTo(x + radius, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.closePath();
}

function drawCanvasText(ctx, value, x, y, options = {}) {
  ctx.fillStyle = options.fill || "#111";
  ctx.font = `${options.weight || 400} ${options.size || 18}px ${FONT_FAMILY}`;
  ctx.textAlign = options.anchor === "middle" ? "center" : options.anchor === "end" ? "right" : "left";
  ctx.textBaseline = "alphabetic";
  ctx.fillText(value, x, y);
}

async function drawCanvasAvatar(ctx, x, y, size, character) {
  if (character.avatarFile) {
    try {
      const image = await loadCanvasImage(getAvatarSrc(character.avatarFile));
      ctx.save();
      ctx.beginPath();
      ctx.arc(x + size / 2, y + size / 2, size / 2, 0, Math.PI * 2);
      ctx.clip();
      const ratio = Math.max(size / image.width, size / image.height);
      const drawWidth = image.width * ratio;
      const drawHeight = image.height * ratio;
      ctx.drawImage(image, x + (size - drawWidth) / 2, y + (size - drawHeight) / 2, drawWidth, drawHeight);
      ctx.restore();
    } catch (error) {
      drawCanvasTextAvatar(ctx, x, y, size, character.avatarText || "人");
      return;
    }

    ctx.strokeStyle = "#111";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(x + size / 2, y + size / 2, size / 2, 0, Math.PI * 2);
    ctx.stroke();
    return;
  }

  drawCanvasTextAvatar(ctx, x, y, size, character.avatarText || "人");
}

function drawCanvasTextAvatar(ctx, x, y, size, text) {
  ctx.fillStyle = "#fff";
  ctx.strokeStyle = "#111";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(x + size / 2, y + size / 2, size / 2, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
  drawCanvasText(ctx, text, x + size / 2, y + size / 2 + 8, {
    size: 22,
    weight: 700,
    anchor: "middle",
    fill: "#111",
  });
}

function drawCanvasBubble(ctx, x, y, width, height, side) {
  ctx.fillStyle = side === "left" ? "#fff" : "#f0f0f0";
  ctx.strokeStyle = "#111";
  ctx.lineWidth = 2;
  drawRoundRect(ctx, x, y, width, height, 10);
  ctx.fill();
  ctx.stroke();

  ctx.beginPath();
  if (side === "left") {
    ctx.moveTo(x, y + 20);
    ctx.lineTo(x - 10, y + 28);
    ctx.lineTo(x, y + 36);
  } else {
    ctx.moveTo(x + width, y + 20);
    ctx.lineTo(x + width + 10, y + 28);
    ctx.lineTo(x + width, y + 36);
  }
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
}

function computeCanvasLayout() {
  const width = Number(els.pageWidth.value);
  const padding = 26;
  const headerHeight = 76;
  const avatarSize = 42;
  const gap = 16;
  const bubbleMaxWidth = Math.min(430, Math.max(230, width - 170));
  const fontSize = 21;
  const lineHeight = 30;
  let y = headerHeight + 24;

  const rows = state.messages.map((message) => {
    const character = getCharacter(message.characterId);
    const side = character.side;
    const isRight = side === "right" || side === "rightNoAvatar";
    const showAvatar = side !== "rightNoAvatar";
    const lines = wrapText(message.text, bubbleMaxWidth - 34, fontSize);
    const textWidth = Math.min(
      bubbleMaxWidth,
      Math.max(96, ...lines.map((line) => measureText(line, fontSize) + 34)),
    );
    const bubbleHeight = lines.length * lineHeight + 26;
    const rowHeight = Math.max(bubbleHeight + 34, avatarSize + 34);
    const avatarX = isRight ? width - padding - avatarSize : padding;
    const bubbleX = isRight
      ? width - padding - textWidth - (showAvatar ? avatarSize + gap : 0)
      : avatarX + avatarSize + gap;
    const nameX = isRight ? bubbleX + textWidth : bubbleX;
    const nameAnchor = isRight ? "end" : "start";
    const row = {
      message,
      character,
      isRight,
      showAvatar,
      lines,
      textWidth,
      bubbleHeight,
      avatarX,
      bubbleX,
      nameX,
      nameAnchor,
      y,
      fontSize,
      lineHeight,
      avatarSize,
    };
    y += rowHeight;
    return row;
  });

  return { width, height: y + 22, padding, headerHeight, rows };
}

async function downloadPng() {
  const layout = computeCanvasLayout();
  const scale = 2;
  const canvas = document.createElement("canvas");
  canvas.width = layout.width * scale;
  canvas.height = layout.height * scale;
  const ctx = canvas.getContext("2d");
  ctx.scale(scale, scale);

  ctx.fillStyle = "#fff";
  ctx.fillRect(0, 0, layout.width, layout.height);
  ctx.fillStyle = "#111";
  ctx.fillRect(0, 0, layout.width, layout.headerHeight);
  drawCanvasText(ctx, els.title.value || "對話", layout.padding, 48, {
    size: 25,
    weight: 700,
    fill: "#fff",
  });

  for (const row of layout.rows) {
    if (row.showAvatar) {
      await drawCanvasAvatar(ctx, row.avatarX, row.y, row.avatarSize, row.character);
    }

    drawCanvasText(ctx, row.character.name, row.nameX, row.y + 14, {
      size: 14,
      fill: "#333",
      anchor: row.nameAnchor,
    });
    drawCanvasBubble(ctx, row.bubbleX, row.y + 22, row.textWidth, row.bubbleHeight, row.isRight ? "right" : "left");

    row.lines.forEach((line, lineIndex) => {
      drawCanvasText(ctx, line, row.bubbleX + 17, row.y + 56 + lineIndex * row.lineHeight, {
        size: row.fontSize,
        fill: "#111",
      });
    });

    if (els.showTime.checked && row.message.time) {
      drawCanvasText(ctx, row.message.time, row.isRight ? row.bubbleX - 10 : row.bubbleX + row.textWidth + 10, row.y + row.bubbleHeight + 18, {
        size: 13,
        fill: "#555",
        anchor: row.isRight ? "end" : "start",
      });
    }
  }

  canvas.toBlob((blob) => {
    if (blob) downloadBlob(blob, "line-chat-image-maker.png");
  }, "image/png");
}
function printPdf() {
  renderSvg();
  window.print();
}

function renderAll() {
  renderEditors();
  renderMessages();
  renderSvg();
}

els.title.addEventListener("input", renderSvg);
els.pageWidth.addEventListener("change", renderSvg);
els.showTime.addEventListener("change", renderSvg);
els.addCharacter.addEventListener("click", () => {
  state.characters.push({
    id: uid("character"),
    name: `角色 ${state.characters.length + 1}`,
    side: "left",
    avatarType: "image",
    avatarFile: avatarOptions[1].value,
    avatarText: `${state.characters.length + 1}`,
  });
  renderAll();
});
els.addMessage.addEventListener("click", () => {
  state.messages.push({ characterId: state.characters[0].id, time: "09:00", text: "請輸入對話內容。" });
  renderAll();
});
els.downloadPng.addEventListener("click", downloadPng);
els.downloadSvg.addEventListener("click", downloadSvg);
els.printPdf.addEventListener("click", printPdf);

renderAll();







